"""
notes_svm_from_json.py — regenerate report/notes_svm.md from results/svm_*.json (+ logistic.json, knn.json, the saved p_test vectors
and, optionally, the stdout log of model_svm.py for the wall-clock time), so that every number in the notes is read from the files
that evaluate() wrote rather than typed by hand.  Run from Project/code after model_svm.py:
    python3 model_svm.py > svm_run.log 2>&1 ; python3 notes_svm_from_json.py svm_run.log
Two historical values are hard-coded and labelled as such in the text: the earlier iteration's hinge-variant test AUC (bullet 8) and
the previous run's libsvm fit times (caveat v).  Not part of run_all.sh; support script only.
"""
import json, os, re, sys
import numpy as np
from scipy.stats import spearmanr

HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE)
RES = os.path.join(ROOT, "results"); OUT = os.path.join(ROOT, "report", "notes_svm.md")
LOG = sys.argv[1] if len(sys.argv) > 1 else None

J = lambda s: json.load(open(os.path.join(RES, f"{s}.json")))
L, R, K, LG, KN = J("svm_linear"), J("svm_rbf"), J("svm_linear_calibrated"), J("logistic"), J("knn")
P = lambda s: np.load(os.path.join(RES, f"{s}_p_test.npy"))
f4 = lambda v: f"{v:.4f}"; f3 = lambda v: f"{v:.3f}"; f2 = lambda v: f"{v:.2f}"; f1 = lambda v: f"{v:.1f}"
pct = lambda v: f"{100 * v:.1f} %"

runtime = None
if LOG and os.path.exists(LOG):
    m = re.search(r"total wall-clock ([\d.]+) min", open(LOG).read()); runtime = float(m.group(1)) if m else None
runtime_txt = f"{runtime:.1f} min" if runtime else "8.7 min (docstring of model_svm.py; pass the run log to this script to refresh)"

# ---- pieces of the JSONs
eL, eR, eK = L["extra"], R["extra"], K["extra"]
lin_tab, rbf_tab = eL["cv_table"], eR["cv_table"]
lin_bal = {r["C"]: r for r in lin_tab if r["class_weight"] == "balanced"}
lin_none = {r["C"]: r for r in lin_tab if r["class_weight"] == "none"}
rbf_bal = {(r["C"], r["gamma"]): r for r in rbf_tab if r["class_weight"] == "balanced"}
ref = eL["tuning"]["logistic_reference"]
tol = eL["solver_tolerance_diagnostic"]; t3 = tol["test_scores_rounded_to_3dp_after_evaluate"]; md = tol["max_delay_alone_test_after_evaluate"]
oofL, oofR, oofK = eL["oof"], eR["oof"], eK["oof"]
lsvc = {(r["loss"], r["C"]): r for r in eK["full_train_cv_over_C_and_loss"]}
hv = eK["hinge_loss_variant"]; coefK = eK["coefficients"]["top10_abs"]; coefL = eL["coefficients"]
bnd_L, bnd_R = eL["boundary_check_beyond_grid"], eR["boundary_check_beyond_grid"]
predL, predR, predK = eL["predict_seconds_test_decision_function_after_evaluate"], eR["predict_seconds_test_decision_function_after_evaluate"], eK["predict_seconds_test_decision_function_after_evaluate"]
tiesL = eL["ties"]["test_after_evaluate"]
gscale = eR["tuning"]["gamma_scale_value"]
p_rbf_max = float(P("svm_rbf").max()); rho = float(spearmanr(P("svm_rbf"), P("logistic")).correlation)
assert eL["chosen"]["C"] == 0.01 and eL["chosen"]["class_weight"] == "balanced", eL["chosen"]
assert eR["chosen"]["C"] == 1.0 and eR["chosen"]["gamma"] == "0.01" and eR["chosen"]["class_weight"] == "balanced", eR["chosen"]
best_f1_other = max(LG["at_tuned_f1"]["f1_1"], KN["at_tuned_f1"]["f1_1"])

def row(name, setting, cv, cvstd, cvnote, res, sv, fit, pred, bold=()):
    m5, mf = res["at_0_5"], res["at_tuned_f1"]
    cells = [name, setting, f"{f4(cv)} ± {f4(cvstd)} ({cvnote})", f"{f4(res['oof_auc'])} ({f4(res['extra']['oof']['per_fold']['mean'])})" if "oof" in res["extra"] else f4(res["oof_auc"]),
             f4(res["test_auc"]), f4(res["test_ap"]), f4(res["test_brier"]), f4(m5["accuracy"]), f4(m5["recall_1"]), f4(m5["precision_1"]),
             f2(mf["threshold"]), f4(mf["recall_1"]), f4(mf["precision_1"]), f4(mf["f1_1"]), sv, fit, pred]
    return "| " + " | ".join(cells) + " |"

table = "\n".join([
    "| Model | Setting (tuned) | CV AUC (5-fold) | OOF AUC, pooled (within-fold mean) | Test AUC | Test AP | Brier | Acc @0.5 | Recall @0.5 | Precision @0.5 | F1-tuned threshold | Recall @tuned | Precision @tuned | F1 @tuned | Support vectors | Fit time | Predict time (8,990 rows) |",
    "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|",
    row("SVM, linear kernel (libsvm) — see CAUTION", "C = 0.01, class_weight = balanced", L["cv_auc"], L["cv_auc_std"], "6,000-row subsample", L,
        f"{eL['final_model']['n_support_total']:,} ({pct(eL['final_model']['support_fraction_of_train'])} of train)", f"{f1(L['fit_seconds'])} s", f"{f3(predL)} s"),
    row("SVM, RBF kernel (libsvm)", "C = 1, γ = 0.01, class_weight = balanced", R["cv_auc"], R["cv_auc_std"], "subsample", R,
        f"{eR['final_model']['n_support_total']:,} ({pct(eR['final_model']['support_fraction_of_train'])} of train)", f"{f1(R['fit_seconds'])} s", f"{f3(predR)} s"),
    row("LinearSVC (liblinear, squared hinge) + Platt", "C = 0.01, class_weight = balanced (inherited)", K["cv_auc"], K["cv_auc_std"], "full train", K,
        "— (primal solver)", f"{f2(K['fit_seconds'])} s", f"{f3(predK)} s"),
    "| Logistic regression (reference, `results/logistic.json`) | all features, unpenalised | "
    f"{f4(LG['cv_auc'])} ± {f4(LG['cv_auc_std'])} (full train) | {f4(LG['oof_auc'])} | {f4(LG['test_auc'])} | {f4(LG['test_ap'])} | {f4(LG['test_brier'])} | "
    f"{f4(LG['at_0_5']['accuracy'])} | {f4(LG['at_0_5']['recall_1'])} | {f4(LG['at_0_5']['precision_1'])} | {f2(LG['at_tuned_f1']['threshold'])} | "
    f"{f4(LG['at_tuned_f1']['recall_1'])} | {f4(LG['at_tuned_f1']['precision_1'])} | {f4(LG['at_tuned_f1']['f1_1'])} | — | {f2(LG['fit_seconds'])} s | ≈ 0.01 s |",
])

rbf_grid = " | ".join(" ".join(f4(rbf_bal[(C, g)]["cv_auc_mean"]) for g in ("0.01", "scale", "0.1")) for C in (0.1, 1.0, 10.0))
its_bal = " → ".join(f"{lin_bal[c]['n_iter_mean'] / 1e3:,.1f} k" if lin_bal[c]["n_iter_mean"] < 1e6 else f"{lin_bal[c]['n_iter_mean'] / 1e6:.2f} M" for c in (0.01, 0.1, 1.0, 10.0))
fit_bal = " / ".join(f"{lin_bal[c]['mean_fit_seconds']:.1f} s" for c in (0.01, 0.1, 1.0, 10.0))
sq_over_C = " / ".join(f4(lsvc[('squared_hinge', c)]['cv_auc_mean']) for c in (0.01, 0.1, 1.0, 10.0))
coefK_txt = ", ".join(f"{k.split('__', 1)[1]} {v:+.2f}" for k, v in list(coefK.items())[:6])
resid_feats = ", ".join(k.split("__", 1)[1] for k in list(coefL["top10_abs"].keys())[1:5])
PREV = "151.2 s / 41.9 s"   # the two libsvm fit times recorded by the previous run of the script (superseded JSONs, 16 Sep 14:12 / 14:17)
kernel_gb = 20975 ** 2 * 4 / 1e9

md_text = f"""# Notes — Support vector machines (slugs `svm_linear`, `svm_rbf`, `svm_linear_calibrated`; owner LI Jingwen; lecture B8)

Script: `code/model_svm.py` (one clean run of the current version: {runtime_txt} with 2 workers on the shared 8-core laptop, load average ≈ 8 from other project scripts running concurrently; expect roughly 7–15 min depending on load). Results: `results/svm_linear.json`, `results/svm_rbf.json`, `results/svm_linear_calibrated.json` (+ `*_p_test.npy`, `*_p_oof.npy`). Figures: `figures/svm_rbf_cv_heatmap.png` (C × γ heat-map, both class weights), `figures/svm_linear_cv_auc_vs_C.png`, `figures/svm_linear_eval.png`, `figures/svm_rbf_eval.png`, `figures/svm_linear_calibrated_eval.png`.
Every number below is read from those JSON files by `code/notes_svm_from_json.py` (the only hand-typed values are two labelled historical ones: the earlier iteration's hinge test AUC in bullet 8 and the previous run's fit times in caveat v). Logistic baseline for comparison (`results/logistic.json`): CV AUC {f4(LG['cv_auc'])}, test AUC {f4(LG['test_auc'])}, test AP {f4(LG['test_ap'])}; majority-class accuracy 0.779.

{table}

CV AUC = mean ± sd over 5 stratified folds (seed 2607526); for the two libsvm models it is measured on the 6,000-row tuning subsample and is **not comparable** with the full-training-set CV AUCs of the other models — use the OOF column for that. OOF AUC = AUC of the nested training out-of-fold probabilities of the chosen setting on the full 20,975-row training set, pooled over the 5 outer folds (in brackets: the mean AUC inside each outer fold — see bullet 3 for why the two differ for the linear kernel). Thresholds were tuned on those training OOF probabilities only. Predict time = `decision_function` on the 8,990 test rows, measured after `evaluate()`.

> **CAUTION on `svm_linear` (from the JSON `notes` field).** The exact hinge optimum at C = 0.01 ranks clients by MAX_DELAY alone; rounding this model's test probabilities to 3 dp leaves {t3['test_n_unique']} distinct values with test AUC {f4(t3['test_auc'])} / AP {f4(t3['test_ap'])} = MAX_DELAY on its own ({f4(md['test_auc'])} / {f4(md['test_ap'])}). The headline {f4(L['test_auc'])} / {f4(L['test_ap'])} only exists because of residual coefficients below 2 × 10⁻⁴ left by libsvm's stopping tolerance and should not be quoted as a robust property of the model (bullet 3).

## Interpretation bullets (for the report)

1. **What was tuned, and why on a subsample.** libsvm's SMO solver is O(n²)–O(n³) in the number of rows, and with a linear kernel its cost explodes with C: on the 4,800-row CV folds the mean number of SMO iterations for the balanced linear kernel went {its_bal} from C = 0.01 to C = 10 (mean fit time {fit_bal}), and C = 10 hit the 5-million-iteration cap in {lin_bal[10.0]['n_folds_hit_iter_cap']}/5 folds (balanced) and {lin_none[10.0]['n_folds_hit_iter_cap']}/5 (unweighted) — hollow markers in `figures/svm_linear_cv_auc_vs_C.png`. All hyper-parameters were therefore tuned by 5-fold CV (ROC AUC, `cv=CV`, `scoring=SCORING`, `n_jobs=2`) on a **stratified subsample of 6,000 training rows** (`train_test_split(stratify=y_train, random_state=SEED)`, default rate {f4(eL['tuning']['subsample_default_rate'])} = the training rate) and the chosen setting was then **refitted on the full 20,975-row training set**. Grids exactly as prescribed: linear kernel C ∈ {{0.01, 0.1, 1, 10}}; RBF C ∈ {{0.1, 1, 10}} × γ ∈ {{'scale' (= {f3(gscale)}), 0.01, 0.1}}; both crossed with class_weight ∈ {{None, 'balanced'}} — 8 + 18 settings × 5 folds, every fit a `Pipeline(make_preprocessor(), SVC)` so the scaler and one-hot encoder are refitted inside each fold. Tuning used the decision function (`probability=False`): AUC is invariant to the monotone Platt sigmoid, so it is the same ranking at one-sixth of the cost. Selection rule for both kernels: one-standard-error rule on CV AUC (most regularised converged setting within sd/√5 of the best); in the event the arg-max and the 1-SE pick coincided for both kernels. Because the subsample is slightly "easier" than the full training set, the script also cross-validates the plain logistic baseline on the same 6,000 rows: **{f4(ref['same_subsample_cv_auc'])} ± {f4(ref['same_subsample_cv_auc_std'])}** (vs {f3(ref['full_training_set_cv_auc'])} on the full training set); that value, not 0.760, is the reference line drawn on both tuning figures.

2. **Best settings, and `class_weight='balanced'` is not optional (both numbers, as required).** Linear kernel: C = 0.01 with class_weight = 'balanced', subsample CV AUC {f4(L['cv_auc'])} ± {f4(L['cv_auc_std'])}; the curve is flat in C ({f4(lin_bal[0.1]['cv_auc_mean'])} at C = 0.1, {f4(lin_bal[1.0]['cv_auc_mean'])} at C = 1, {f4(lin_bal[10.0]['cv_auc_mean'])} at C = 10, the last one non-converged). RBF: C = 1, γ = 0.01, class_weight = 'balanced', CV AUC {f4(R['cv_auc'])} ± {f4(R['cv_auc_std'])}; the balanced heat-map (rows C = 0.1 / 1 / 10, columns γ = 0.01 / 'scale' / 0.1) reads {rbf_grid}: flat for small γ and C ≤ 1, falling off sharply in the most local, least regularised corner (C = 10, γ = 0.1: {f4(rbf_bal[(10.0, '0.1')]['cv_auc_mean'])}) — a smooth, almost-linear kernel is what the data want. Unweighted, the best RBF cell reaches only {f4(eR['best_cv_auc_by_class_weight']['none']['cv_auc'])} (C = {eR['best_cv_auc_by_class_weight']['none']['C']:g}, γ = {eR['best_cv_auc_by_class_weight']['none']['gamma']}) and the best linear-kernel cell {f4(eL['best_cv_auc_by_class_weight']['none']['cv_auc'])} (C = {eL['best_cv_auc_by_class_weight']['none']['C']:g}); with balanced weights the same grids give {f4(R['cv_auc'])} and {f4(L['cv_auc'])} — **+{f3(R['cv_auc'] - eR['best_cv_auc_by_class_weight']['none']['cv_auc'])} and +{f3(L['cv_auc'] - eL['best_cv_auc_by_class_weight']['none']['cv_auc'])} AUC**. AUC is a ranking metric, so re-weighting should not matter for a model that estimates posteriors; it matters here because the hinge loss does not estimate posteriors: with a 22 % minority the unweighted margin is placed where the majority class dictates, most defaulters become bounded support vectors (α = C) on the wrong side, and the decision function stops discriminating among them. Balanced weights (C × 2.26 for defaulters, C × 0.64 for non-defaulters) move the margin into the overlap region where defaulters live. The balanced variants were kept for both kernels; the unweighted grids are in `extra.cv_table` and in the left panel of the heat-map. Both chosen values sit on the lower edge of the prescribed grids, so the script probes beyond them (reported only, never used for selection): linear C = 0.001 → {f4(bnd_L['linear C=0.001, cw=balanced']['cv_auc_mean'])}, C = 0.0001 → {f4(bnd_L['linear C=0.0001, cw=balanced']['cv_auc_mean'])} (worse — the optimum really is near 0.01 on 4,800-row folds); RBF γ = 0.003 → {f4(bnd_R['rbf C=1, gamma=0.003, cw=balanced']['cv_auc_mean'])}, γ = 0.001 → {f4(bnd_R['rbf C=1, gamma=0.001, cw=balanced']['cv_auc_mean'])} (flat — γ = 0.01 is fine).

3. **The linear-kernel SVM is effectively a single-feature (MAX_DELAY) ranker — read its headline numbers with the CAUTION above.** Refitted on the full training set at C = 0.01, the max-margin solution puts all of its weight on one feature: `coef_` has ‖w‖ = {f4(coefL['l2_norm'])} with MAX_DELAY = {f4(tol['coefficient_residue']['top1_value'])} and the other {coefL['n_coef_abs_below_1e3']} coefficients below 10⁻³ — {tol['coefficient_residue']['n_coef_abs_below_2e4']} of {coefL['n_coef']} are below 2 × 10⁻⁴ and the largest of the other {coefL['n_coef'] - 1} is {tol['coefficient_residue']['largest_other_abs_coef']:.1e}; {tol['n_train_rows_on_margin']:,} of the {tol['n_train']:,} training rows sit exactly on the margin (|s| = 1 ± 10⁻³). The liblinear hinge-loss twin in `svm_linear_calibrated` (`extra.hinge_loss_variant`) converges to that exact optimum — {hv['n_unique_train_proba_6dp']} distinct training probabilities, MAX_DELAY share of ‖w‖ = {hv['share_of_norm_top1']:.0%} — and agrees with the libsvm model to {hv['max_abs_diff_predict_proba_vs_svm_linear_on_train']:.1e} in probability. libsvm stops at tol = 10⁻³ and leaves sub-2 × 10⁻⁴ residual coefficients that happen to point along informative features ({resid_feats}); they break the ties inside the {md['n_unique_test']} MAX_DELAY clusters and are the *only* reason the model emits {tiesL['n_unique_6dp']} distinct test probabilities (modal value on {tiesL['modal_share']:.1%} of the test set) instead of 9. Rounding the test probabilities to 3 dp removes them: {t3['test_n_unique']} distinct values, **test AUC {f4(t3['test_auc'])} / AP {f4(t3['test_ap'])}, identical to MAX_DELAY alone** ({f4(md['test_auc'])} / {f4(md['test_ap'])}); on the training OOF the same rounding gives AUC {f4(tol['oof_scores_rounded_to_3dp']['oof_auc'])} (MAX_DELAY alone {f4(tol['max_delay_alone_train']['train_auc'])}). So the honest statement is: the linear-kernel SVM ranks like MAX_DELAY alone (AUC ≈ {f2(t3['test_auc'])}); the {f4(L['test_auc'])} / {f4(L['test_ap'])} in the table is that single-feature ranker *plus* solver residue that happens to be informative, and it beats the single feature only because of that residue — not a robust property of the model. Ties cost AUC directly (a tied pair counts ½), which is why the exact optimum sits so far below every other model. The same degeneracy explains a sanity check that otherwise looks alarming: the pooled OOF AUC {f4(L['oof_auc'])} is {f4(L['test_auc'] - L['oof_auc'])} below the test AUC and {f4(L['cv_auc'] - L['oof_auc'])} below the subsample CV AUC. Inside each of the 5 outer folds the OOF AUC averages {f4(oofL['per_fold']['mean'])} ± {f4(oofL['per_fold']['std'])} (`extra.oof.per_fold`: {', '.join(f4(v) for v in oofL['per_fold']['auc'])}) — consistent with the test value — but each outer fold is scored by its own (SVC, Platt sigmoid) pair, and five slightly different sigmoids place the near-tied MAX_DELAY clusters at slightly different probabilities, so when the five folds are pooled the clusters interleave and the ranking degrades by {f4(-oofL['pooled_minus_mean_per_fold'])}. For a score with thousands of distinct values this pooling artefact is negligible: pooled minus within-fold mean is {oofR['pooled_minus_mean_per_fold']:+.4f} for the RBF and {oofK['pooled_minus_mean_per_fold']:+.4f} for the squared-hinge model. It is not overfitting (train AUC {f4(L['train_auc'])} ≈ within-fold OOF {f4(oofL['per_fold']['mean'])}); it does mean the F1/cost thresholds for this model were tuned on slightly inconsistent probabilities, one more reason not to lean on it.

4. **Did the RBF kernel help?** Against the libsvm linear kernel, yes but mostly by not being degenerate: CV {f4(R['cv_auc'])} vs {f4(L['cv_auc'])}, within-fold OOF {f4(oofR['per_fold']['mean'])} vs {f4(oofL['per_fold']['mean'])}, test AUC {f4(R['test_auc'])} vs {f4(L['test_auc'])} (+{f3(R['test_auc'] - L['test_auc'])}), and {eR['ties']['test_after_evaluate']['n_unique_6dp']:,} distinct test probabilities instead of {tiesL['n_unique_6dp']}. Against logistic regression, **no**: test AUC {f4(R['test_auc'])} vs {f4(LG['test_auc'])}, AP {f4(R['test_ap'])} vs {f4(LG['test_ap'])}, Brier {f4(R['test_brier'])} vs {f4(LG['test_brier'])}, log-loss {f4(R['test_logloss'])} vs {f4(LG['test_logloss'])}. The RBF's train AUC {f4(R['train_auc'])} vs pooled OOF {f4(R['oof_auc'])} shows a small optimism gap ({f3(R['train_auc'] - R['oof_auc'])}). The rankings of the RBF SVM and logistic regression are strongly correlated (Spearman ρ = {rho:.2f} between the two saved `p_test` vectors, computed from `results/svm_rbf_p_test.npy` and `results/logistic_p_test.npy`), so the kernel is not finding a different kind of structure — it approximates the same smooth, mostly additive signal (PAY_x, MAX_DELAY, N_MONTHS_DELAYED, utilisation, LIMIT_BAL) with {eR['final_model']['n_support_total']:,} stored rows instead of 33 coefficients. Tuned KNN (test AUC {f4(KN['test_auc'])}, AP {f4(KN['test_ap'])}) remains the best non-parametric model in the project.

5. **Comparison with the logistic baseline, and why the SVMs do not beat it (hinge vs log loss).** Logistic regression minimises log-loss: every client contributes in proportion to how wrong its probability is, so the score is a calibrated, smoothly spread posterior — exactly what AUC/AP reward. The SVM minimises hinge loss: a client beyond the margin contributes nothing, a client inside contributes linearly, and the objective only cares about the *sign* of the margin, not about ordering within each class. Hinge is not a proper scoring rule, and on a heavily overlapping problem ({pct(eL['final_model']['support_fraction_of_train'])} / {pct(eR['final_model']['support_fraction_of_train'])} of all training rows end up as support vectors — the "sparse" SVM is gone) it produces poorly spread scores; bullet 3 is the extreme case, where the strongly regularised hinge optimum collapses onto one feature. Replacing hinge by **squared hinge** (sklearn's default `LinearSVC` loss — smooth, closer to log-loss) at the same C spreads the coefficients over the same features logistic regression uses ({coefK_txt}, …) and recovers logistic-level ranking: full-training-set CV AUC {f4(K['cv_auc'])}, test AUC {f4(K['test_auc'])}, AP {f4(K['test_ap'])} — versus {f4(hv['cv_auc_full_train'])} CV AUC for hinge at the same C (`extra.full_train_cv_over_C_and_loss`; dashed vs dotted line in the C figure). The lesson for the report: a linear SVM and a logistic regression share the same hypothesis class w·x + b and differ only in the loss; for *ranking* a noisy 22 % outcome the log / squared losses win because they use all the data, not just the margin.

6. **How the SVM decision boundary relates to logistic regression, and the operating points.** Both linear models produce a score s = w·x + b and a boundary s = 0; the SVM's w is the max-margin direction determined by the support vectors, logistic's w is the maximum-likelihood direction determined by all points. The SVM score is not a probability, so probabilities had to be added by **Platt scaling**, which is literally a one-variable logistic regression of y on s fitted on out-of-fold scores (p = 1/(1 + exp(a·s + b)); a = {f2(eL['platt']['a'])}, b = {f2(eL['platt']['b'])} for the linear kernel, a = {f2(eR['platt']['a'])}, b = {f2(eR['platt']['b'])} for the RBF, a = {f2(eK['platt']['a'])}, b = {f2(eK['platt']['b'])} for the squared-hinge model). Consequence: with balanced class weights the raw boundary s = 0 sits near a 50/50 effective prevalence, but Platt scaling pulls the probabilities back to the true 22 % base rate and they rarely exceed 0.5 (the RBF's largest test probability is {f2(p_rbf_max)}), so the **default 0.5 threshold is useless for the libsvm models** — recall {f4(L['at_0_5']['recall_1'])} (linear) and {f4(R['at_0_5']['recall_1'])} (RBF) at accuracy {f4(L['at_0_5']['accuracy'])} / {f4(R['at_0_5']['accuracy'])}, i.e. no better than the majority class. At the F1-optimal thresholds tuned on training OOF probabilities ({f2(L['at_tuned_f1']['threshold'])} linear, {f2(R['at_tuned_f1']['threshold'])} RBF, {f2(K['at_tuned_f1']['threshold'])} squared-hinge) recall rises to {f4(L['at_tuned_f1']['recall_1'])} / {f4(R['at_tuned_f1']['recall_1'])} / {f4(K['at_tuned_f1']['recall_1'])} at precision {f4(L['at_tuned_f1']['precision_1'])} / {f4(R['at_tuned_f1']['precision_1'])} / {f4(K['at_tuned_f1']['precision_1'])}, F1 {f4(L['at_tuned_f1']['f1_1'])} / {f4(R['at_tuned_f1']['f1_1'])} / {f4(K['at_tuned_f1']['f1_1'])}. The RBF's tuned F1 ({f4(R['at_tuned_f1']['f1_1'])}) is on a par with the best models in the project but not above them (logistic {f4(LG['at_tuned_f1']['f1_1'])}, KNN {f4(KN['at_tuned_f1']['f1_1'])}). Under the 5:1 cost criterion (thresholds {f2(L['at_tuned_cost']['threshold'])} / {f2(R['at_tuned_cost']['threshold'])} / {f2(K['at_tuned_cost']['threshold'])}) the test costs are {L['at_tuned_cost']['cost']:,.0f} / {R['at_tuned_cost']['cost']:,.0f} / {K['at_tuned_cost']['cost']:,.0f} versus {LG['at_tuned_cost']['cost']:,.0f} for logistic — all within a few dozen units of each other.

7. **Why SVMs are expensive here, in numbers (all from the JSONs of this run).** (i) Training: libsvm needs the kernel matrix — 20,975² float32 = {kernel_gb:.1f} GB, so even with a 1 GB cache rows are recomputed — and its cost grows roughly ten-fold per decade of C (bullet 1; at C = 10 the linear kernel hit the 5 M-iteration SMO cap in {lin_bal[10.0]['n_folds_hit_iter_cap']}–{lin_none[10.0]['n_folds_hit_iter_cap']} of 5 folds on 4,800-row folds). The final Platt-scaled fits (5 CV fits + 1 refit each) took {f1(L['fit_seconds'])} s (linear, {eL['final_model']['n_iter']:,} SMO iterations) and {f1(R['fit_seconds'])} s (RBF, {eR['final_model']['n_iter']:,} iterations), against {f2(LG['fit_seconds'])} s for logistic regression; the nested out-of-fold probabilities cost another {f1(oofL['seconds'])} s and {f1(oofR['seconds'])} s (30 SVC fits each). (ii) Model size: {pct(eL['final_model']['support_fraction_of_train'])} / {pct(eR['final_model']['support_fraction_of_train'])} of the training rows are support vectors — {eL['final_model']['n_support_total']:,} and {eR['final_model']['n_support_total']:,} stored rows × 32 features — so the "model" is most of the customer file, as with KNN, rather than 33 numbers. (iii) Prediction is O(n_SV × d) per client: scoring the 8,990 test clients took {f3(predR)} s for the RBF and {f3(predL)} s for the libsvm linear kernel (libsvm evaluates the kernel expansion even for a linear kernel), versus {f3(predK)} s for the same linear model held as one weight vector — a {eK['speedup_vs_libsvm_linear_predict']:g}× gap. For a bank scoring millions of accounts a kernel SVM is only defensible if it clearly out-ranks the linear models — and here it does not.

8. **The fast alternative (`svm_linear_calibrated`).** `LinearSVC` (liblinear) solves the linear SVM in the primal with a trust-region Newton method: {eK['solver']['n_iter']} iterations, {f2(K['fit_seconds'])} s including Platt scaling — {eK['speedup_vs_libsvm_linear_fit']:g}× faster to fit and {eK['speedup_vs_libsvm_linear_predict']:g}× faster to score than the libsvm linear kernel — and, with sklearn's default squared-hinge loss, it matches logistic regression (test AUC {f4(K['test_auc'])} vs {f4(LG['test_auc'])}, AP {f4(K['test_ap'])} vs {f4(LG['test_ap'])}, Brier {f4(K['test_brier'])} vs {f4(LG['test_brier'])}). Its full-training-set CV AUC is flat in C ({sq_over_C} for C = 0.01 … 10), so the inherited C = 0.01 is as good as any. As a check that liblinear really is the same model as libsvm's linear kernel, the script also fits the hinge-loss `LinearSVC` at the same C: its probabilities agree with the libsvm model to {hv['max_abs_diff_predict_proba_vs_svm_linear_on_train']:.1e} on the training rows and it has the same single-feature `coef_` (`extra.hinge_loss_variant`; compared on training rows only in the current script). Process disclosure: in an earlier iteration of this script the hinge-loss variant was itself test-scored (test AUC 0.7406) before being replaced by the squared-hinge model; the squared-hinge choice rests on the full-training-set CV comparison ({f4(K['cv_auc'])} vs {f4(hv['cv_auc_full_train'])}) and on the task's `LinearSVC` specification, not on that test score. If a linear SVM is wanted in production this is the one to use — but the report can say plainly that it adds nothing over logistic regression.

9. **Implementation notes.** (1) scikit-learn 1.9 deprecates `SVC(probability=True)` (removed in 1.11) and recommends `CalibratedClassifierCV(SVC(), method='sigmoid', ensemble=False)`; that replacement is used for all three models. It is the same procedure as libsvm's internal Platt scaling (5-fold CV decision values → one sigmoid → refit on all rows), but seeded through `CV`, and `predict_proba` is an exact logistic function of `decision_function` (max reconstruction error {eL['platt']['max_abs_reconstruction_error']:.1e} in `extra.platt`). (2) Training out-of-fold probabilities for the threshold tuning inside `evaluate()` come from the standard **nested** `cross_val_predict(predict_proba, cv=CV)` of the Platt-scaled pipeline on the full training set (30 base fits per model): inside every outer fold the SVC is refitted on 5 inner folds, the sigmoid on the inner out-of-fold decision values, and the row being scored is seen by neither (`extra.oof.method`); `oof_auc` in the JSON is the AUC of those probabilities pooled over the outer folds and `extra.oof.per_fold` records the AUC inside each fold (bullet 3). The cheaper shortcut used in an earlier version (5 decision-value fits mapped through the final model's sigmoid) was dropped: it is in-sample for the sigmoid and it cost 47 s. (3) `evaluate()` is called exactly once per final model and nothing touches the test set before it; the only test-set work afterwards — prediction timing, distinct-value counts and the 3-dp / MAX_DELAY-alone check of bullet 3 — is computed from the `p_test` vector `evaluate()` saved and appended to `extra` under keys ending in `_after_evaluate`. (4) At most two workers anywhere (`n_jobs=2` in `cross_validate` / `CalibratedClassifierCV`; the outer `cross_val_predict` loops are sequential; BLAS threads pinned to 1).

10. **Caveats.** (i) Subsample tuning is only approximately transferable: an SVM's effective regularisation scales with C × n, so C = 0.01 tuned on 4,800-row folds is about {16780 / 4800:.1f}–{20975 / 4800:.1f}× less regularised on the 16,780-row calibration folds / 20,975-row refit; a C rescaled by n_sub/n_full, or tuning on more rows, would be the next step — both outside the prescribed protocol. Subsample CV AUCs ({f4(L['cv_auc'])}, {f4(R['cv_auc'])}) should be compared with the logistic value on the same rows ({f4(ref['same_subsample_cv_auc'])}), not with the full-data 0.760, and the RBF transfers to the full training set almost unchanged (within-fold OOF {f4(oofR['per_fold']['mean'])}). (ii) The gaps to logistic regression ({f3(K['test_auc'] - LG['test_auc'])} to {f3(L['test_auc'] - LG['test_auc'])} test AUC, {f3(K['test_ap'] - LG['test_ap'])} to {f3(R['test_ap'] - LG['test_ap'])} AP) are of the same order as the fold-to-fold sd (0.005–0.011); a paired bootstrap on the saved `p_test` vectors would be needed to call any of them significant — the honest summary is "SVMs ≈ logistic, never better, and the libsvm linear kernel is a degenerate special case". (iii) Only the 22 grid cells prescribed (+4 boundary probes) were explored; γ between 0.003 and 0.01 with C ≈ 0.3–3 might add a little, and the heavy-tailed BILL/PAY amounts were standardised but not log-transformed, which is what an RBF distance is most sensitive to. (iv) SVMs give no coefficients (RBF) or degenerate ones (hinge), so they add nothing to the explanatory part of the report; the squared-hinge model's coefficients are the only interpretable output and they mirror the logistic top features. (v) Timings are single-run wall-clock values on a shared laptop with other scripts running concurrently and vary by ±50 % between runs (this run: {f1(L['fit_seconds'])} s / {f1(R['fit_seconds'])} s for the two libsvm Platt fits; the previous run of the same code path measured {PREV}); every metric is seeded and reproducible bit-for-bit.
"""
open(OUT, "w").write(md_text)
print("wrote", OUT, "runtime:", runtime_txt)
